-- OPS installer-only envelope for frozen retention196; not a business rewrite.
-- Existing installer RET edge inheritance and RET public CREATE are temporary,
-- restored exactly inside this transaction. No business functions are invoked.
BEGIN;
SET LOCAL search_path=pg_catalog;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
DO $qualified_retention_install$
DECLARE
 source bytea:=decode('','hex');
 executable bytea;
 original_memberships jsonb;
 original_roles jsonb;
 original_acls jsonb;
 old_retention_relation_oids oid[];
 restored_acls jsonb;
BEGIN
 IF current_user<>'postgres' OR NOT EXISTS(SELECT FROM pg_roles WHERE rolname='postgres'
  AND NOT rolsuper AND rolinherit AND rolbypassrls) THEN
  RAISE EXCEPTION 'ops_retention_qualified_nonsuper_installer_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='gridex_ediel_retention_owner'
  AND NOT rolcanlogin AND NOT rolsuper AND NOT rolinherit AND NOT rolcreatedb AND NOT rolcreaterole
  AND NOT rolreplication AND rolbypassrls AND rolconfig IS NULL AND rolconnlimit=-1 AND rolvaliduntil IS NULL) THEN RAISE EXCEPTION 'ops_retention_owner_shape_drift';END IF;
 IF (SELECT jsonb_agg(jsonb_build_array(g.rolname,m.admin_option,m.inherit_option,m.set_option)
  ORDER BY g.rolname COLLATE "C") FROM pg_auth_members m JOIN pg_roles g ON g.oid=m.grantor
  WHERE m.roleid=(SELECT oid FROM pg_roles WHERE rolname='gridex_ediel_retention_owner')
   AND m.member=(SELECT oid FROM pg_roles WHERE rolname='postgres')) IS DISTINCT FROM
   '[ ["postgres",false,false,true],["supabase_admin",true,false,false] ]'::jsonb
  OR EXISTS(SELECT FROM pg_auth_members WHERE roleid=(SELECT oid FROM pg_roles WHERE rolname='gridex_ediel_retention_owner')
    AND member<>(SELECT oid FROM pg_roles WHERE rolname='postgres')) THEN
  RAISE EXCEPTION 'ops_retention_existing_controlled_edges_required';END IF;
 IF EXISTS(SELECT FROM pg_roles WHERE rolname IN('anon','authenticated','service_role','authenticator')
  AND(pg_has_role(oid,'gridex_ediel_retention_owner','MEMBER')OR pg_has_role(oid,'gridex_ediel_retention_owner','SET')
   OR pg_has_role(oid,'gridex_ediel_retention_owner','USAGE'))) THEN
  RAISE EXCEPTION 'ops_retention_app_owner_membership_drift';END IF;
 IF pg_has_role('postgres','gridex_ediel_retention_owner','USAGE') OR NOT pg_has_role('postgres','gridex_ediel_retention_owner','SET')
  OR NOT has_schema_privilege('postgres','public','CREATE WITH GRANT OPTION')
  OR has_schema_privilege('gridex_ediel_retention_owner','public','CREATE') THEN
  RAISE EXCEPTION 'ops_retention_installer_effective_capabilities_drift';END IF;
 IF NOT EXISTS(SELECT FROM pg_namespace WHERE nspname='public'
  AND nspowner=(SELECT oid FROM pg_roles WHERE rolname='pg_database_owner') AND nspacl=ARRAY['pg_database_owner=UC/pg_database_owner','=U/pg_database_owner','postgres=U/pg_database_owner','anon=U/pg_database_owner','authenticated=U/pg_database_owner','service_role=U/pg_database_owner','gridex_ediel_retention_owner=U/pg_database_owner']::aclitem[])
  OR NOT EXISTS(SELECT FROM pg_namespace WHERE nspname='gridex_ediel_retention'
   AND nspowner=(SELECT oid FROM pg_roles WHERE rolname='gridex_ediel_retention_owner') AND nspacl=ARRAY['gridex_ediel_retention_owner=UC/gridex_ediel_retention_owner','postgres=U/gridex_ediel_retention_owner']::aclitem[]) THEN
  RAISE EXCEPTION 'ops_retention_known_schema_owner_acl_required';END IF;
 -- Existing native retention foundations remain owner-only before temporary inheritance.
 IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='gridex_ediel_retention' AND c.relname IN
   ('record_class_catalog','record_decisions','record_reviews','record_tombstones')
  AND c.relkind='r' AND c.relowner=(SELECT oid FROM pg_roles WHERE rolname='gridex_ediel_retention_owner')
  AND c.relacl=ARRAY['gridex_ediel_retention_owner=arwdDxtm/gridex_ediel_retention_owner']::aclitem[])<>4
  OR EXISTS(SELECT FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
   JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gridex_ediel_retention'
    AND c.relname IN('record_class_catalog','record_decisions','record_reviews','record_tombstones') AND a.attacl IS NOT NULL) THEN
  RAISE EXCEPTION 'ops_retention_existing_owner_only_table_column_acl_required';END IF;
 IF octet_length(source)<>43134 OR encode(sha256(source),'hex')<>'19624482d3a4df867e999848e8b7b8ed72f9c8f2b4962ebb3c75b369c937d4ad' THEN
  RAISE EXCEPTION 'ops_retention_original_source_bytes_drift';END IF;
 executable:=substring(source,1,399)||substring(source,407,42720)||substring(source,43135);
 IF octet_length(executable)<>43119 OR encode(sha256(executable),'hex')<>'418eb6adde3491d12a06a518cc1807c17ca8e49ad90c698187d0bff18a7310df' THEN
  RAISE EXCEPTION 'ops_retention_executable_bytes_drift';END IF;
 original_memberships:=(SELECT jsonb_agg(to_jsonb(m) ORDER BY m.oid) FROM pg_auth_members m
  WHERE m.roleid=(SELECT oid FROM pg_roles WHERE rolname='gridex_ediel_retention_owner'));
 original_roles:=(SELECT jsonb_agg(to_jsonb(r)-'rolpassword' ORDER BY r.oid) FROM pg_roles r);
 SELECT coalesce(array_agg(c.oid ORDER BY c.oid),ARRAY[]::oid[]) INTO old_retention_relation_oids
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gridex_ediel_retention';
 SELECT jsonb_build_object('namespaces',(SELECT jsonb_agg(jsonb_build_array(n.oid,n.nspname,n.nspowner,n.nspacl)ORDER BY n.oid)FROM pg_namespace n WHERE n.nspname IN('public','gridex_ediel_retention')),'retention_tables',(SELECT jsonb_agg(jsonb_build_array(c.oid,c.relname,c.relowner,c.relacl)ORDER BY c.oid)FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gridex_ediel_retention'AND c.oid=ANY(old_retention_relation_oids)),'retention_columns',(SELECT jsonb_agg(jsonb_build_array(a.attrelid,a.attnum,a.attacl)ORDER BY a.attrelid,a.attnum)FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gridex_ediel_retention'AND c.oid=ANY(old_retention_relation_oids))) INTO original_acls;
 GRANT gridex_ediel_retention_owner TO postgres WITH ADMIN FALSE,INHERIT TRUE,SET TRUE GRANTED BY postgres;
 GRANT CREATE ON SCHEMA public TO gridex_ediel_retention_owner;
 IF NOT pg_has_role('postgres','gridex_ediel_retention_owner','USAGE')
  OR NOT has_schema_privilege('gridex_ediel_retention_owner','public','CREATE') THEN
  RAISE EXCEPTION 'ops_retention_temporary_install_capabilities_unavailable';END IF;
 EXECUTE convert_from(executable,'UTF8');
 REVOKE CREATE ON SCHEMA public FROM gridex_ediel_retention_owner;
 GRANT gridex_ediel_retention_owner TO postgres WITH ADMIN FALSE,INHERIT FALSE,SET TRUE GRANTED BY postgres;
 IF original_memberships IS DISTINCT FROM(SELECT jsonb_agg(to_jsonb(m)ORDER BY m.oid)FROM pg_auth_members m
   WHERE m.roleid=(SELECT oid FROM pg_roles WHERE rolname='gridex_ediel_retention_owner'))
  OR original_roles IS DISTINCT FROM(SELECT jsonb_agg(to_jsonb(r)-'rolpassword'ORDER BY r.oid)FROM pg_roles r)
  OR pg_has_role('postgres','gridex_ediel_retention_owner','USAGE')
  OR has_schema_privilege('gridex_ediel_retention_owner','public','CREATE') THEN
  RAISE EXCEPTION 'ops_retention_all_roles_and_membership_oids_must_restore';END IF;
 SELECT jsonb_build_object('namespaces',(SELECT jsonb_agg(jsonb_build_array(n.oid,n.nspname,n.nspowner,n.nspacl)ORDER BY n.oid)FROM pg_namespace n WHERE n.nspname IN('public','gridex_ediel_retention')),'retention_tables',(SELECT jsonb_agg(jsonb_build_array(c.oid,c.relname,c.relowner,c.relacl)ORDER BY c.oid)FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gridex_ediel_retention'AND c.oid=ANY(old_retention_relation_oids)),'retention_columns',(SELECT jsonb_agg(jsonb_build_array(a.attrelid,a.attnum,a.attacl)ORDER BY a.attrelid,a.attnum)FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gridex_ediel_retention'AND c.oid=ANY(old_retention_relation_oids))) INTO restored_acls;
 IF restored_acls IS DISTINCT FROM original_acls THEN
  RAISE EXCEPTION 'ops_retention_all_existing_schema_table_column_acls_must_restore';END IF;
END;
$qualified_retention_install$;
COMMIT;
